import React, { useState, useRef, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { X, User, ShieldCheck, ArrowRight, AlertCircle, Phone, RefreshCw } from 'lucide-react';
import Logo from './Logo';
import styles from './LoginModal.module.css';
import { auth } from '../firebase';
import { signInWithPhoneNumber, RecaptchaVerifier } from 'firebase/auth';
import api from '../services/api';

export default function LoginModal() {
  const { loginModalOpen, closeLoginModal, loginWithPhone } = useAuth();

  const [step, setStep] = useState(1);           // 1 = Name & Phone, 2 = OTP
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [resendTimer, setResendTimer] = useState(30);
  const [confirmationResult, setConfirmationResult] = useState(null);

  const otpInputsRef = useRef([]);
  const recaptchaVerifierRef = useRef(null);
  const recaptchaMountedRef = useRef(false);

  // Reset everything when modal opens/closes
  useEffect(() => {
    if (loginModalOpen) {
      setStep(1);
      setError('');
      setLoading(false);
      setOtp(['', '', '', '', '', '']);
      setResendTimer(30);
      setConfirmationResult(null);
    } else {
      // Clean up reCAPTCHA when modal closes
      cleanupRecaptcha();
    }
  }, [loginModalOpen]);

  // Countdown timer for resend
  useEffect(() => {
    if (step === 2 && resendTimer > 0) {
      const t = setInterval(() => setResendTimer((v) => v - 1), 1000);
      return () => clearInterval(t);
    }
  }, [step, resendTimer]);

  // Auto-focus first OTP box
  useEffect(() => {
    if (step === 2) {
      setTimeout(() => otpInputsRef.current[0]?.focus(), 120);
    }
  }, [step]);

  if (!loginModalOpen) return null;

  const cleanPhone = phone.replace(/\D/g, '').slice(-10);

  // ─── reCAPTCHA helpers ────────────────────────────────────────────────────
  function cleanupRecaptcha() {
    if (recaptchaVerifierRef.current) {
      try { recaptchaVerifierRef.current.clear(); } catch (_) {}
      recaptchaVerifierRef.current = null;
    }
    recaptchaMountedRef.current = false;
  }

  async function getRecaptchaVerifier() {
    // Always clear old verifier first to avoid "already-exists" errors
    cleanupRecaptcha();

    const container = document.getElementById('recaptcha-container');
    if (!container) throw new Error('reCAPTCHA container not found in DOM');

    const verifier = new RecaptchaVerifier(auth, 'recaptcha-container', {
      size: 'invisible',
      callback: () => {},
      'expired-callback': () => {
        cleanupRecaptcha();
      },
    });

    // Render (pre-solves invisible reCAPTCHA)
    await verifier.render();
    recaptchaVerifierRef.current = verifier;
    recaptchaMountedRef.current = true;
    return verifier;
  }

  // ─── Step 1: Send OTP via Firebase ───────────────────────────────────────
  const handleSendOtp = async (e) => {
    e?.preventDefault();
    setError('');

    if (!name.trim()) { setError('Please enter your full name'); return; }
    if (cleanPhone.length !== 10) { setError('Please enter a valid 10-digit mobile number'); return; }

    setLoading(true);
    try {
      const phoneWithCountry = `+91${cleanPhone}`;
      const verifier = await getRecaptchaVerifier();
      const result = await signInWithPhoneNumber(auth, phoneWithCountry, verifier);
      setConfirmationResult(result);
      setStep(2);
      setResendTimer(30);
      setOtp(['', '', '', '', '', '']);
    } catch (err) {
      console.error('Firebase OTP error:', err.code, err.message);
      cleanupRecaptcha();
      setError(getFriendlyError(err));
    } finally {
      setLoading(false);
    }
  };

  // ─── Step 2: Verify OTP ────────────────────────────────────────────────
  const handleVerifyOtp = async (e) => {
    e?.preventDefault();
    const enteredOtp = otp.join('');
    if (enteredOtp.length !== 6) { setError('Please enter all 6 digits'); return; }

    setError('');
    setLoading(true);
    try {
      if (!confirmationResult) throw new Error('Session expired. Please resend OTP.');

      // Confirm OTP with Firebase
      const userCredential = await confirmationResult.confirm(enteredOtp);
      const firebaseToken = await userCredential.user.getIdToken();

      // Exchange Firebase token for our backend JWT
      const res = await api.post('/auth/firebase-phone-login', {
        firebaseToken,
        name: name.trim(),
        phone: cleanPhone,
      });

      if (res.data?.success) {
        localStorage.setItem('pb_token', res.data.token);
        closeLoginModal();
        window.location.reload();
      } else {
        throw new Error(res.data?.message || 'Login failed');
      }
    } catch (err) {
      console.error('OTP verify error:', err.code, err.message);
      setError(getFriendlyError(err));
    } finally {
      setLoading(false);
    }
  };

  // ─── OTP box interactions ─────────────────────────────────────────────
  const handleOtpChange = (idx, val) => {
    const char = val.replace(/\D/g, '').slice(-1);
    const next = [...otp];
    next[idx] = char;
    setOtp(next);
    if (char && idx < 5) otpInputsRef.current[idx + 1]?.focus();
    // Auto-submit when all 6 filled
    if (char && idx === 5 && next.every((d) => d)) {
      submitOtp(next.join(''));
    }
  };

  const handleOtpKeyDown = (idx, e) => {
    if (e.key === 'Backspace' && !otp[idx] && idx > 0) {
      otpInputsRef.current[idx - 1]?.focus();
    }
  };

  const handleOtpPaste = (e) => {
    const pasted = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, 6);
    if (pasted.length === 6) {
      setOtp(pasted.split(''));
      setTimeout(() => submitOtp(pasted), 50);
    }
  };

  const submitOtp = async (code) => {
    if (!confirmationResult || loading) return;
    setError('');
    setLoading(true);
    try {
      const userCredential = await confirmationResult.confirm(code);
      const firebaseToken = await userCredential.user.getIdToken();
      const res = await api.post('/auth/firebase-phone-login', {
        firebaseToken,
        name: name.trim(),
        phone: cleanPhone,
      });
      if (res.data?.success) {
        localStorage.setItem('pb_token', res.data.token);
        closeLoginModal();
        window.location.reload();
      } else {
        throw new Error(res.data?.message || 'Login failed');
      }
    } catch (err) {
      setError(getFriendlyError(err));
      setLoading(false);
    }
  };

  // ─── Error messages ───────────────────────────────────────────────────
  function getFriendlyError(err) {
    const code = err?.code || '';
    const msg  = err?.message || '';
    if (code === 'auth/operation-not-allowed')
      return 'Phone sign-in is not enabled. Please contact support.';
    if (code === 'auth/invalid-phone-number')
      return 'Invalid phone number. Please check and try again.';
    if (code === 'auth/too-many-requests')
      return 'Too many attempts. Please wait a few minutes and try again.';
    if (code === 'auth/captcha-check-failed')
      return 'reCAPTCHA failed. Please refresh the page and try again.';
    if (code === 'auth/invalid-verification-code' || msg.includes('invalid-verification-code'))
      return 'Incorrect OTP. Please check the code and try again.';
    if (code === 'auth/code-expired' || msg.includes('expired'))
      return 'OTP has expired. Please request a new one.';
    if (code === 'auth/session-expired')
      return 'Session expired. Please resend OTP.';
    if (code === 'auth/network-request-failed')
      return 'Network error. Please check your internet connection.';
    return err?.response?.data?.message || msg || 'Something went wrong. Please try again.';
  }

  // ─── Render ───────────────────────────────────────────────────────────
  return (
    <div className={styles.overlay} onClick={(e) => { if (e.target === e.currentTarget) closeLoginModal(); }}>
      {/* Invisible reCAPTCHA anchor – must stay in DOM throughout step 1 */}
      <div id="recaptcha-container" style={{ position: 'fixed', bottom: 0, right: 0, zIndex: -1 }} />

      <div className={styles.modal} role="dialog" aria-modal="true" aria-label="Login">
        {/* Close */}
        <button className={styles.closeBtn} onClick={closeLoginModal} aria-label="Close">
          <X size={20} strokeWidth={2.2} />
        </button>

        {/* Header */}
        <div className={styles.brandWrap}>
          <Logo theme="forest" />
        </div>
        <div className={styles.header}>
          <div className={styles.headerIcon}>
            {step === 1 ? <Phone size={22} strokeWidth={2} /> : <ShieldCheck size={22} strokeWidth={2} />}
          </div>
          <h2 className={styles.title}>
            {step === 1 ? 'Sign in to ProBridge' : 'Verify your number'}
          </h2>
        </div>

        {/* Step dots */}
        <div className={styles.stepIndicator}>
          <div className={`${styles.stepDot} ${step >= 1 ? styles.stepActive : ''}`}>1</div>
          <div className={styles.stepLine} />
          <div className={`${styles.stepDot} ${step >= 2 ? styles.stepActive : ''}`}>2</div>
        </div>

        {/* OTP destination on step 2 */}
        {step === 2 && (
          <p className={styles.otpSubtitle}>
            OTP sent to <strong>+91 {cleanPhone}</strong>&nbsp;
            <button className={styles.editPhoneBtn} onClick={() => { setStep(1); setError(''); setOtp(['','','','','','']); }}>
              Edit
            </button>
          </p>
        )}

        {/* Error banner */}
        {error && (
          <div className={styles.errorBanner}>
            <AlertCircle size={16} />
            <span>{error}</span>
          </div>
        )}

        {/* ── STEP 1: Name & Mobile ── */}
        {step === 1 ? (
          <form onSubmit={handleSendOtp} className={styles.form}>
            <div className={styles.field}>
              <label className={styles.label}>Full Name</label>
              <div className={styles.inputWrap}>
                <User size={18} className={styles.fieldIcon} />
                <input
                  type="text"
                  className={styles.input}
                  placeholder="Enter your full name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  autoFocus
                  required
                />
              </div>
            </div>

            <div className={styles.field}>
              <label className={styles.label}>Mobile Number</label>
              <div className={styles.phoneInputWrap}>
                <div className={styles.countryCode}>
                  <span>🇮🇳</span>
                  <span>+91</span>
                </div>
                <input
                  type="tel"
                  className={styles.phoneInput}
                  placeholder="10-digit mobile number"
                  maxLength={10}
                  value={phone}
                  onChange={(e) => setPhone(e.target.value.replace(/\D/g, ''))}
                  required
                />
              </div>
            </div>

            <button
              type="submit"
              className={styles.submitBtn}
              disabled={loading || !name.trim() || cleanPhone.length !== 10}
            >
              {loading
                ? <><span className={styles.spinner} />Sending OTP…</>
                : <><span>Send OTP</span><ArrowRight size={17} /></>
              }
            </button>
          </form>
        ) : (
          /* ── STEP 2: OTP ── */
          <form onSubmit={handleVerifyOtp} className={styles.form}>
            <div className={styles.otpInputWrap} onPaste={handleOtpPaste}>
              {otp.map((digit, idx) => (
                <input
                  key={idx}
                  ref={(el) => (otpInputsRef.current[idx] = el)}
                  type="text"
                  inputMode="numeric"
                  maxLength={1}
                  className={`${styles.otpDigit} ${digit ? styles.otpDigitFilled : ''}`}
                  value={digit}
                  onChange={(e) => handleOtpChange(idx, e.target.value)}
                  onKeyDown={(e) => handleOtpKeyDown(idx, e)}
                />
              ))}
            </div>

            <button
              type="submit"
              className={styles.submitBtn}
              disabled={loading || otp.some((d) => d === '')}
            >
              {loading
                ? <><span className={styles.spinner} />Verifying…</>
                : <><ShieldCheck size={18} /><span>Verify &amp; Login</span></>
              }
            </button>

            {/* Resend row */}
            <div className={styles.resendRow}>
              {resendTimer > 0 ? (
                <span>Resend OTP in <span className={styles.resendTimer}>{resendTimer}s</span></span>
              ) : (
                <button
                  type="button"
                  className={styles.resendBtn}
                  onClick={handleSendOtp}
                  disabled={loading}
                >
                  <RefreshCw size={14} /> Resend OTP
                </button>
              )}
            </div>
          </form>
        )}

        <p className={styles.termsText}>
          By continuing, you agree to ProBridge's Terms of Service and Privacy Policy.
        </p>
      </div>
    </div>
  );
}
